package dev.relay.engine;
import com.fasterxml.jackson.databind.JsonNode;import dev.relay.domain.CreateOrderRequest.PaymentScenario;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.UUID;
@Service public class OrderActivityService {
 private final JdbcTemplate jdbc;public OrderActivityService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public void reserve(UUID workflowId,JsonNode order)throws Exception {String existing=jdbc.query("select status from inventory_reservations where workflow_id=?",rs->rs.next()?rs.getString(1):null,workflowId);if("ACTIVE".equals(existing))return;String sku=order.path("sku").asText();int qty=order.path("quantity").asInt();int updated=jdbc.update("update inventory_items set available=available-? where sku=? and available>=?",qty,sku,qty);if(updated==0)throw new IllegalStateException("Inventory unavailable for SKU "+sku+" (or SKU is unknown)");if("RELEASED".equals(existing))jdbc.update("update inventory_reservations set status='ACTIVE' where workflow_id=?",workflowId);else jdbc.update("insert into inventory_reservations(workflow_id,order_id,sku,quantity) values(?,?,?,?)",workflowId,order.path("orderId").asText(),sku,qty);}
 @Transactional public void charge(UUID workflowId,JsonNode order,int attempt)throws Exception {if(jdbc.queryForObject("select count(*) from payments where workflow_id=?",Integer.class,workflowId)>0)return;PaymentScenario scenario=PaymentScenario.valueOf(order.path("paymentScenario").asText("APPROVE"));if(scenario==PaymentScenario.FAIL_ONCE&&attempt==1)throw new ActivityRunner.SimulatedFailure("Payment gateway timed out; retry will safely recover");if(scenario==PaymentScenario.DECLINE)throw new IllegalStateException("Payment declined by the demo payment gateway");jdbc.update("insert into payments(workflow_id,order_id,amount,status) values(?,?,?,'CAPTURED') on conflict(workflow_id) do nothing",workflowId,order.path("orderId").asText(),new BigDecimal(order.path("amount").asText()));}
 @Transactional public void ship(UUID workflowId,JsonNode order)throws Exception {if(jdbc.queryForObject("select count(*) from shipments where workflow_id=?",Integer.class,workflowId)>0)return;String tracking="RLY-"+order.path("orderId").asText().replaceAll("[^A-Za-z0-9]","-");jdbc.update("insert into shipments(workflow_id,order_id,tracking_code,status) values(?,?,?,'LABEL_CREATED') on conflict(workflow_id) do nothing",workflowId,order.path("orderId").asText(),tracking);}
 @Transactional public void notifyCustomer(UUID workflowId,JsonNode order)throws Exception {jdbc.update("insert into customer_notifications(workflow_id,order_id,recipient,message) values(?,?,?,?) on conflict(workflow_id) do nothing",workflowId,order.path("orderId").asText(),order.path("email").asText(),"Order "+order.path("orderId").asText()+" is packed and ready for dispatch.");}

 @Transactional public boolean compensate(UUID workflowId)throws Exception {if(jdbc.queryForObject("select count(*) from payments where workflow_id=?",Integer.class,workflowId)>0)return false;var rows=jdbc.query("select sku,quantity from inventory_reservations where workflow_id=? and status='ACTIVE' for update",(rs,n)->new Object[]{rs.getString(1),rs.getInt(2)},workflowId);if(rows.isEmpty())return false;Object[] r=rows.get(0);jdbc.update("update inventory_items set available=available+? where sku=?",r[1],r[0]);jdbc.update("update inventory_reservations set status='RELEASED' where workflow_id=?",workflowId);return true;}
}
